-- Cases de Wealth Management (docs/cases: PDF "Wealth Management — Cases, Perguntas e Conteúdo"). Todos os dados são fictícios.
-- wm-simplificado: a conversa com Camila e a comparação de três propostas. wm-complexo: o patrimônio de Helena Prado.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'wm-simplificado',
  $$WM simplificado: ajudar Camila a organizar seu patrimônio$$,
  'wealth-management',
  $$Converse com uma cliente que acaba de receber R$ 2,4 milhões, entenda seus objetivos e limite de risco e compare as propostas de três casas.$$,
  $$Entender o que Camila pede, comparar três propostas e apresentar a ela uma recomendação com a principal concessão e as condições para avançar.$$,
  $$Você trabalha em uma equipe de Wealth Management e vai ajudar Camila, 41 anos, a escolher como organizar seu patrimônio. Ela vendeu sua participação em uma startup de tecnologia e recebeu R$ 2,4 milhões líquidos, hoje parados na conta corrente. Camila quer comprar um apartamento em cerca de dois anos, com uns R$ 800 mil, e destinar o restante à independência financeira, daqui a 15 ou 20 anos. Ela aceita oscilações, mas uma queda de mais de 15% em um ano lhe tiraria o sono. Todos os nomes, empresas e números são fictícios.$$,
  $${"resumo":"Wealth Management é a área que assessora pessoas e famílias na gestão do patrimônio: investimentos, planejamento financeiro, proteção, tributação e sucessão, sempre a partir dos objetivos da cliente. Neste case, você ajuda Camila, uma cliente fictícia que acaba de receber R$ 2,4 milhões, a entender o que ela precisa e a comparar três propostas.","links":[],"cards":[{"titulo":"O que é Wealth Management","texto":"Assessora pessoas e famílias na gestão do patrimônio: investimentos, planejamento financeiro, proteção, tributação e sucessão. O ponto de partida é sempre o objetivo da cliente, não o produto.","naPratica":"Perguntar “o que esse dinheiro precisa fazer por você?” revela mais do que perguntar só “qual retorno você quer?”."},{"titulo":"Modelos de atuação","texto":"Private banking é a área de um banco que atende clientes de alto patrimônio com uma banker dedicada. Assessoria de investimentos distribui e explica produtos. Consultoria de investimentos, registrada na CVM, recomenda investimentos, em geral com remuneração paga pela própria cliente. Gestão de patrimônio e family office decidem pela cliente ou cuidam de várias necessidades da família. Planejamento financeiro integra orçamento, metas, aposentadoria, seguros e sucessão.","naPratica":"Neste case, cada proposta vem de um modelo diferente, e o modelo muda como a casa é remunerada e quem executa as ordens."},{"titulo":"Perfil e suitability","texto":"A instituição avalia se os produtos são adequados ao perfil, aos objetivos e à situação financeira da cliente, conforme as regras da CVM. A tolerância a risco combina o que a cliente diz com o que ela faz.","naPratica":"Se o comportamento da cliente contradiz o questionário, a conversa vale mais do que a pontuação."},{"titulo":"Separação por objetivos","texto":"O patrimônio é dividido em partes com finalidades diferentes: reserva, objetivos de curto prazo e crescimento de longo prazo. Cada parte tem risco compatível com seu prazo.","naPratica":"O dinheiro do apartamento fica em renda fixa com vencimento próximo; o da independência financeira pode ter mais ações."},{"titulo":"Retorno, perda em estresse, custo e liquidez","texto":"Retorno esperado e perda estimada em estresse são estimativas, não garantias. O custo total inclui taxas e outras formas de remuneração, e pequenas diferenças se acumulam ao longo do tempo. Liquidez é a facilidade de transformar um investimento em dinheiro sem perder valor relevante.","naPratica":"Uma carteira com retorno esperado alto e perda possível acima do que a cliente aceita pode ser inadequada, mesmo que pareça atraente."}],"comoSeEntra":{"ondeSeTrabalha":"Private banking de bancos, escritórios de assessoria de investimentos, consultorias de investimentos, gestoras de patrimônio e family offices, e planejamento financeiro.","formacoes":"Desde janeiro de 2026, as certificações de distribuição da ANBIMA são CPA, C-Pro R e C-Pro I. A CPA é a porta de entrada e pré-requisito para as demais; para planejamento financeiro, a certificação de referência é a CFP®.","vagas":"No estágio, o trabalho costuma ser apoiar relatórios, pesquisas de produtos, cadastro e preparação de reuniões. Depois vêm analista, assessora ou banker, banker sênior e head ou diretora. Os títulos e a divisão do trabalho variam entre instituições.","oQueAjuda":"Excel, comunicação (explicar conceitos técnicos de forma simples), conhecimento de produtos, ética e escuta: colocar o interesse da cliente em primeiro lugar e ser transparente sobre remuneração.","quandoRecrutam":"Os prazos variam entre as instituições. Acompanhe as páginas de carreira dos bancos, escritórios e consultorias."}}$$::jsonb,
  'publicado',
  7
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
('wm-conteudo-modelos', $$O que é Wealth Management e como se atua$$, 'artigo', 'wealth-management', $$Os cinco modelos de atuação e o que cada um faz.$$, $$**Wealth Management (WM)** assessora pessoas e famílias na gestão do patrimônio: investimentos, planejamento financeiro, proteção, tributação e sucessão, sempre a partir dos objetivos da cliente. Há modelos de atuação diferentes. No **private banking**, uma área de um banco atende clientes de alto patrimônio com uma banker dedicada e acesso a produtos do banco e de terceiros. Na **assessoria de investimentos**, escritórios ligados a uma corretora ou plataforma distribuem e explicam produtos. Na **consultoria de investimentos**, um profissional ou empresa registrada na CVM recomenda investimentos, em geral com remuneração paga pela própria cliente, que executa as ordens na corretora de sua escolha. A **gestão de patrimônio e o family office** decidem pela cliente dentro de um mandato ou cuidam de várias necessidades de uma família, como investimentos, contabilidade, imóveis e governança. O **planejamento financeiro** organiza orçamento, metas, aposentadoria, seguros e sucessão, integrando todas as partes da vida financeira.$$, NULL, 6, '["wm-simplificado","wm-complexo"]'::jsonb),
('wm-conteudo-carreira', $$Carreira, certificações e o que as vagas exigem$$, 'artigo', 'wealth-management', $$Como a carreira evolui, quais certificações existem no Brasil e o que as vagas pedem.$$, $$A carreira costuma evoluir de **estágio** (relatórios, pesquisas de produtos, cadastro e preparação de reuniões) para **analista** (propostas de carteira, acompanhamento de posições e materiais para clientes), **assessora ou banker** (atende uma carteira de clientes e cuida do relacionamento), **banker sênior** (clientes de maior patrimônio e coordenação de especialistas) e **head ou diretora** (lidera equipes, metas e a estratégia comercial). Os títulos e a divisão do trabalho variam entre instituições. Desde janeiro de 2026, as certificações de distribuição da ANBIMA são **CPA, C-Pro R e C-Pro I**, que substituíram CPA-10, CPA-20 e CEA: a CPA é a porta de entrada e pré-requisito para as demais, a C-Pro R é voltada ao relacionamento com investidores e a C-Pro I, à parte técnica de recomendação de carteiras. Para planejamento financeiro, a certificação de referência é a **CFP®**. As vagas pedem **Excel** (organizar posições, calcular retornos, projetar patrimônio e comparar cenários), **comunicação** (explicar conceitos técnicos de forma simples), **conhecimento de produtos** (renda fixa, fundos, ações, previdência, com riscos, custos e tributação) e **ética e escuta** (interesse da cliente em primeiro lugar e transparência sobre a remuneração).$$, NULL, 5, '["wm-simplificado"]'::jsonb),
('wm-conteudo-jornada', $$A jornada com a cliente$$, 'artigo', 'wealth-management', $$Descoberta, perfil, proposta e acompanhamento.$$, $$A jornada tem quatro etapas. Na **descoberta**, a primeira conversa levanta objetivos, prazos, renda, gastos, família, patrimônio, experiência e relação com risco; perguntar “o que esse dinheiro precisa fazer por você?” revela mais do que perguntar só “qual retorno você quer?”. No **perfil (suitability)**, a instituição avalia se os produtos são adequados ao perfil, aos objetivos e à situação financeira da cliente, conforme as regras da CVM; se o comportamento da cliente contradiz o questionário, a conversa vale mais do que a pontuação. Na **proposta**, a equipe define a estratégia: separação por objetivos, alocação entre classes de ativos, reserva de liquidez, proteção e sucessão. Uma proposta boa explica por que cada parte existe e qual risco a cliente está aceitando. No **acompanhamento**, a carteira é monitorada, rebalanceada e revisada quando a vida da cliente muda (casamento, filhos, venda de empresa, aposentadoria); a revisão anual é uma oportunidade para atualizar objetivos, não só para mostrar rentabilidade.$$, NULL, 5, '["wm-simplificado"]'::jsonb),
('wm-conteudo-conceitos', $$Risco, liquidez e retorno real$$, 'glossario', 'wealth-management', $$Três perguntas que toda carteira precisa responder.$$, $$**Risco e retorno:** retornos maiores geralmente vêm acompanhados de mais oscilação ou risco de perda; não existe investimento com alto retorno e risco zero. Em WM, olhe qual perda a cliente aceitaria em um ano ruim, se o retorno esperado compensa o risco e se a carteira está concentrada em poucos ativos ou emissores. Uma carteira com retorno esperado de 7% e perda possível de 30% pode ser inadequada para quem precisa do dinheiro em dois anos. **Liquidez** é a facilidade de transformar um investimento em dinheiro sem perder valor relevante; alguns produtos têm carência ou prazo de resgate. Se a cliente vai comprar um imóvel em 18 meses, um título com vencimento em cinco anos pode obrigá-la a vender antes, possivelmente com perda. **Retorno real** desconta a inflação e mostra o ganho de poder de compra; para planos de longo prazo, é a medida que importa. Confira se os gastos futuros e o retorno projetado estão na mesma base: um investimento que rende 10% com inflação de 6% aumenta o poder de compra em cerca de 3,8%, não em 10%.$$, NULL, 6, '["wm-simplificado","wm-complexo"]'::jsonb),
('wm-conteudo-alocacao', $$Classes de ativos e alocação$$, 'artigo', 'wealth-management', $$As classes de ativos, o retorno esperado ponderado, a diversificação e o rebalanceamento.$$, $$As principais classes são: **renda fixa pós-fixada** (acompanha uma taxa como o CDI ou a Selic; reserva, liquidez e estabilidade), **renda fixa atrelada à inflação** (inflação mais uma taxa; protege o poder de compra no longo prazo), **renda fixa prefixada** (taxa definida na compra; oscila com os juros antes do vencimento), **crédito privado** (títulos de empresas ou bancos, como debêntures; retorno adicional em troca de risco de crédito), **ações** (crescimento de longo prazo, com mais oscilação), **fundos e ETFs** (diversificação e gestão profissional ou passiva) e **investimentos no exterior** (diversificação geográfica e cambial). A **alocação de ativos** é a divisão do patrimônio entre classes e, em geral, explica mais do resultado de longo prazo do que a escolha de cada produto. O retorno esperado da carteira é a média ponderada: com 60% em renda fixa a 5% e 40% em ações a 9%, o retorno é 0,6 × 5% + 0,4 × 9% = 6,6%. **Diversificar** reduz o impacto de problemas isolados; **rebalancear** devolve a carteira aos pesos planejados quando o mercado os altera. Se as ações subiram e passaram de 40% para 50% da carteira, rebalancear reduz o risco de volta ao nível escolhido.$$, NULL, 7, '["wm-simplificado","wm-complexo"]'::jsonb),
('wm-conteudo-objetivos', $$Separação por objetivos e projeção patrimonial$$, 'artigo', 'wealth-management', $$Como dividir o patrimônio por finalidade e projetar se os objetivos são viáveis.$$, $$Na **separação por objetivos**, o patrimônio é dividido em partes com finalidades diferentes: reserva, objetivos de curto prazo e crescimento de longo prazo. Cada parte tem risco compatível com seu prazo; o dinheiro do apartamento fica em renda fixa com vencimento próximo, e o da aposentadoria pode ter mais ações. A **projeção patrimonial** estima a evolução do patrimônio ao longo dos anos, considerando retorno, aportes, retiradas e eventos previstos, e ajuda a responder se os objetivos são viáveis. Se o patrimônio necessário para sustentar a aposentadoria é maior que o projetado, a cliente pode poupar mais, gastar menos, trabalhar por mais tempo ou aceitar mais risco. Em Excel, organize o fluxo ano a ano, informe quando cada entrada e saída começa e termina e mantenha a coerência entre valores reais e retornos reais.$$, NULL, 5, '["wm-simplificado","wm-complexo"]'::jsonb),
('wm-conteudo-custos', $$Custos e remuneração$$, 'glossario', 'wealth-management', $$Quanto a cliente paga no total e como a casa é remunerada.$$, $$Taxas de administração, performance, corretagem e spreads reduzem o retorno líquido, e pequenas diferenças se acumulam ao longo do tempo. Ao comparar propostas, olhe quanto a cliente paga no total, como a instituição ou a profissional é remunerada e se o custo é compatível com o serviço. Custos embutidos nas taxas dos produtos, taxas fixas explícitas e receitas recebidas de produtos distribuídos são formas diferentes de remuneração, e cada uma pode criar conflitos de interesse diferentes.$$, NULL, 3, '["wm-simplificado"]'::jsonb),
('wm-conteudo-tributacao', $$Tributação e proteção (FGC)$$, 'artigo', 'wealth-management', $$Imposto de renda na renda fixa, dividendos e o que o FGC cobre.$$, $$Na renda fixa, o IR segue a **tabela regressiva**: 22,5% até 180 dias, 20% de 181 a 360, 17,5% de 361 a 720 e 15% acima de 720 dias. LCI e LCA seguem isentas para pessoa física. Desde 2026, dividendos acima de R$ 50 mil por mês, pagos pela mesma empresa à mesma pessoa, têm retenção de 10%, e rendas anuais acima de R$ 600 mil podem estar sujeitas a uma tributação mínima. Compare sempre o retorno líquido: um produto isento com taxa menor pode render mais que um tributado com taxa maior. O **FGC** cobre até R$ 250 mil por CPF por conglomerado financeiro, com teto global de R$ 1 milhão a cada quatro anos, em produtos como CDB, LCI, LCA e poupança. Títulos públicos, fundos, ações e COEs não têm essa cobertura. Com R$ 1 milhão em renda fixa bancária, dividir entre quatro conglomerados diferentes mantém tudo dentro da cobertura. As regras refletem o que estava em vigor no Brasil em novembro de 2026 e devem ser revisadas. Fontes citadas no material de referência: Lei nº 15.270/2025 (Planalto), retenção de 10% sobre dividendos (Conjur), novas certificações da ANBIMA, limites do FGC (InfoMoney) e a queda da MP 1.303, com manutenção da tabela regressiva e das isenções.$$, NULL, 6, '["wm-simplificado","wm-complexo"]'::jsonb),
('wm-conteudo-sucessao', $$Previdência e sucessão$$, 'artigo', 'wealth-management', $$PGBL, VGBL e as ferramentas de sucessão patrimonial.$$, $$O **PGBL** permite deduzir contribuições até 12% da renda tributável na declaração completa, mas o IR no resgate incide sobre o valor total. No **VGBL**, o IR incide só sobre os rendimentos. A tabela regressiva da previdência chega a 10% após dez anos. A previdência também pode ser usada no planejamento sucessório, mas as regras de ITCMD mudaram recentemente em vários estados e precisam ser verificadas. Na **sucessão**, sem planejamento os bens passam pelo inventário, com ITCMD e custos. Havendo herdeiros necessários, metade do patrimônio é a legítima. Testamento, doação em vida com usufruto, previdência e holding são ferramentas possíveis, cada uma com custos e limites. O que olhar: quem são os herdeiros, se há empresa ou imóveis, se a família conversa sobre o tema e quais são as regras do estado da cliente.$$, NULL, 5, '["wm-complexo"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

