('wm-cp-1', 'wm-simplificado', 1, 'entenda', $$O trabalho em Wealth Management$$, $$Conheça o que faz uma equipe de WM, os modelos de atuação e como a conversa com a cliente começa pelos objetivos dela.$$, 15, $$[]$$::jsonb),
('wm-cp-2', 'wm-simplificado', 2, 'conteudos', $$Conteúdos do case$$, $$Leia todos os conteúdos do case antes de conversar com Camila e comparar as propostas.$$, 10, $$[]$$::jsonb),
('wm-cp-3', 'wm-simplificado', 3, 'situacao', $$A conversa com Camila$$, $$Entenda o que Camila pede e traduza a conversa em objetivos, prazos e limite de risco.$$, 30, $$["wm-task-conversa"]$$::jsonb),
('wm-cp-4', 'wm-simplificado', 4, 'situacao', $$Entenda as propostas$$, $$Para cada casa, escolha o maior atrativo e o maior risco para Camila e proponha um ajuste.$$, 35, $$["wm-task-horizonte","wm-task-vertice","wm-task-prumo","wm-task-negociacao"]$$::jsonb),
('wm-cp-5', 'wm-simplificado', 5, 'situacao', $$Comparando as propostas$$, $$Compare retorno, perda em estresse, custo e liquidez e faça uma recomendação inicial.$$, 30, $$["wm-task-comparacao"]$$::jsonb),
('wm-cp-6', 'wm-simplificado', 6, 'situacao', $$Nova informação$$, $$Reaja a uma nova necessidade de Camila e à resposta da Vértice.$$, 25, $$["wm-task-nova-informacao"]$$::jsonb),
('wm-cp-7', 'wm-simplificado', 7, 'defesa', $$Pitch final$$, $$Apresente a recomendação a Camila, com a principal concessão e as condições para avançar.$$, 40, $$["wm-task-pitch"]$$::jsonb)
