INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
('wm-task-conversa', 'wm-simplificado', 'wm-cp-3', $$A conversa com Camila$$, $$Você trabalha em uma equipe de Wealth Management e vai ajudar Camila, 41 anos, a escolher como organizar seu patrimônio. Ela vendeu sua participação em uma startup de tecnologia e recebeu R$ 2,4 milhões líquidos. Hoje o dinheiro está parado na conta corrente. Todos os nomes, empresas e números deste case são fictícios. Camila conta:
Camila: “Quero comprar um apartamento em cerca de dois anos e vou separar uns R$ 800 mil para isso. O restante é para a minha independência financeira, daqui a 15 ou 20 anos.”
Camila: “Já vi meu patrimônio cair 40% quando a startup passou por uma crise e não quero viver isso de novo. Aceito oscilações, mas uma queda de mais de 15% em um ano me tiraria o sono.”
Camila: “Não entendo de produtos complexos e quero saber o que tenho. Também ajudo minha mãe com R$ 4 mil por mês e quero continuar ajudando.”
[[continuar]]
[[campos: pergunta_1]]
Pergunta 1 — O dinheiro do apartamento.
[[continuar]]
[[campos: pergunta_2]]
Pergunta 2 — Tolerância a risco.
[[continuar]]
[[campos: pergunta_3]]
Pergunta 3 — Simplicidade.
[[continuar]]
[[campos: aberta_1]]
Pergunta aberta 1 — Preparar a próxima conversa. Você pode fazer uma pergunta adicional a Camila antes de apresentar propostas.$$, $$[{"id":"pergunta_1","tipo":"opcao","rotulo":"Qual alternativa respeita melhor o objetivo do apartamento?","obrigatorio":true,"opcoes":["A. Investir os R$ 800 mil em ações para que o valor cresça mais rápido até a compra.","B. Aplicar os R$ 800 mil em renda fixa de baixo risco, com vencimentos próximos à data da compra e emissores diversificados.","C. Aplicar os R$ 800 mil em um plano de previdência para reduzir impostos.","D. Aplicar os R$ 800 mil em fundos imobiliários, porque o objetivo é imobiliário."]},{"id":"pergunta_2","tipo":"opcao","rotulo":"Como você deve interpretar o que Camila disse sobre perdas?","obrigatorio":true,"opcoes":["A. Ela aceita oscilações moderadas; a carteira de longo prazo deve ter perda estimada em cenário de estresse abaixo de 15%, e ainda é preciso confirmar como ela reagiria na prática.","B. Ela não aceita nenhuma oscilação e deve manter tudo em aplicações de liquidez diária.","C. Como o horizonte é longo, a opinião dela sobre perdas pode ser desconsiderada.","D. Ela aceita qualquer perda, desde que o retorno esperado seja alto."]},{"id":"pergunta_3","tipo":"opcao","rotulo":"O que significa Camila dizer que não entende de produtos complexos?","obrigatorio":true,"opcoes":["A. Ela proíbe qualquer investimento além da poupança.","B. Ela delega todas as decisões e não quer ser informada.","C. Ela prefere uma carteira que consiga entender; produtos complexos só fariam sentido se trouxessem um benefício claro e fossem bem explicados.","D. Ela quer apenas os produtos com maior retorno, independentemente da estrutura."]},{"id":"aberta_1","tipo":"texto","rotulo":"O que você perguntaria a Camila e como a resposta mudaria sua recomendação? (até 60 palavras)","obrigatorio":true,"limiteCaracteres":420}]$$::jsonb, NULL, $${"referencias":{"pergunta_1":"B. Aplicar os R$ 800 mil em renda fixa de baixo risco, com vencimentos próximos à data da compra e emissores diversificados.","pergunta_2":"A. Ela aceita oscilações moderadas; a carteira de longo prazo deve ter perda estimada em cenário de estresse abaixo de 15%, e ainda é preciso confirmar como ela reagiria na prática.","pergunta_3":"C. Ela prefere uma carteira que consiga entender; produtos complexos só fariam sentido se trouxessem um benefício claro e fossem bem explicados."},"justificativas":{"pergunta_1":"Objetivo de curto prazo pede baixo risco, vencimento compatível e diversificação de emissores. A e D expõem o valor a oscilações; C tem horizonte e regras inadequados ao prazo.","pergunta_2":"Traduz a fala em um limite concreto sem ignorar a necessidade de confirmar o comportamento real.","pergunta_3":"Reconhece a preferência sem inventar uma proibição absoluta."},"avaliacao":{"aberta_1":"Uma dúvida específica, por exemplo se a data do apartamento é flexível ou se há outras reservas, e como a resposta mudaria a alocação."}}$$::jsonb),
('wm-task-horizonte', 'wm-simplificado', 'wm-cp-4', $$Proposta — Banco Horizonte$$, $$Proposta 1 — Banco Horizonte. Private bank de um grande banco. Oferece atendimento com uma banker dedicada e carteira composta principalmente por fundos da própria casa. O custo está embutido nas taxas dos fundos.
Camila recebeu propostas de três casas. Para esta proposta, selecione uma opção como maior atrativo e outra como maior risco para Camila. As duas escolhas devem ser diferentes.$$, $$[{"id":"atrativo","tipo":"opcao","rotulo":"Banco Horizonte — maior atrativo para Camila","obrigatorio":true,"opcoes":["1. A banker dedicada pode acompanhar Camila de perto e explicar a carteira.","2. A carteira se concentra em fundos da própria instituição.","3. O banco é grande e tem marca conhecida.","4. O custo embutido nas taxas dos fundos é o mais alto entre as propostas.","5. A carteira de longo prazo tem a menor perda estimada em estresse.","6. O banco oferece também cartão de crédito e seguros."]},{"id":"risco","tipo":"opcao","rotulo":"Banco Horizonte — maior risco para Camila (diferente do atrativo escolhido)","obrigatorio":true,"opcoes":["1. A banker dedicada pode acompanhar Camila de perto e explicar a carteira.","2. A carteira se concentra em fundos da própria instituição.","3. O banco é grande e tem marca conhecida.","4. O custo embutido nas taxas dos fundos é o mais alto entre as propostas.","5. A carteira de longo prazo tem a menor perda estimada em estresse.","6. O banco oferece também cartão de crédito e seguros."]}]$$::jsonb, NULL, $${"referencias":{"atrativo":"1. A banker dedicada pode acompanhar Camila de perto e explicar a carteira.","risco":"4. O custo embutido nas taxas dos fundos é o mais alto entre as propostas."},"outrasEscolhasDefensaveis":["Risco 2: concentração em fundos da casa também se liga a conflito de interesse e a um CDB de um único emissor acima do limite do FGC."],"cuidado":"Um retorno esperado alto não é automaticamente o maior atrativo para Camila. Ele só ajuda se vier com um risco que ela aceite e produtos que ela entenda. Os dois campos precisam ser diferentes."}$$::jsonb),
('wm-task-vertice', 'wm-simplificado', 'wm-cp-4', $$Proposta — Vértice Consultoria$$, $$Proposta 2 — Vértice Consultoria. Consultoria de investimentos independente, registrada na CVM. Cobra uma taxa fixa sobre o patrimônio e não recebe remuneração dos produtos. Recomenda títulos públicos e ETFs. As ordens são executadas pela própria cliente em sua corretora.
Camila recebeu propostas de três casas. Para esta proposta, selecione uma opção como maior atrativo e outra como maior risco para Camila. As duas escolhas devem ser diferentes.$$, $$[{"id":"atrativo","tipo":"opcao","rotulo":"Vértice Consultoria — maior atrativo para Camila","obrigatorio":true,"opcoes":["1. A remuneração fixa, sem comissões dos produtos, reduz conflitos de interesse.","2. Camila terá de executar as ordens sozinha na corretora.","3. A consultoria não tem fundos próprios.","4. Títulos públicos e ETFs são produtos relativamente simples de entender.","5. A perda estimada em estresse fica próxima do limite de Camila.","6. A consultoria é menor do que um grande banco."]},{"id":"risco","tipo":"opcao","rotulo":"Vértice Consultoria — maior risco para Camila (diferente do atrativo escolhido)","obrigatorio":true,"opcoes":["1. A remuneração fixa, sem comissões dos produtos, reduz conflitos de interesse.","2. Camila terá de executar as ordens sozinha na corretora.","3. A consultoria não tem fundos próprios.","4. Títulos públicos e ETFs são produtos relativamente simples de entender.","5. A perda estimada em estresse fica próxima do limite de Camila.","6. A consultoria é menor do que um grande banco."]}]$$::jsonb, NULL, $${"referencias":{"atrativo":"1. A remuneração fixa, sem comissões dos produtos, reduz conflitos de interesse.","risco":"2. Camila terá de executar as ordens sozinha na corretora."},"outrasEscolhasDefensaveis":["Atrativo 4: simplicidade dos produtos atende ao pedido de Camila.","Risco 5: perda próxima do limite."],"cuidado":"Os dois campos precisam ser diferentes."}$$::jsonb),
('wm-task-prumo', 'wm-simplificado', 'wm-cp-4', $$Proposta — Prumo Investimentos$$, $$Proposta 3 — Prumo Investimentos. Escritório de assessoria de investimentos com grande variedade de produtos. Propõe uma carteira com ações de tecnologia, crédito privado de maior risco e um COE para o dinheiro do apartamento. Cobra uma taxa explícita baixa, mas recebe parte das receitas de alguns produtos.
Camila recebeu propostas de três casas. Para esta proposta, selecione uma opção como maior atrativo e outra como maior risco para Camila. As duas escolhas devem ser diferentes.$$, $$[{"id":"atrativo","tipo":"opcao","rotulo":"Prumo Investimentos — maior atrativo para Camila","obrigatorio":true,"opcoes":["1. A taxa explícita é a menor entre as propostas.","2. A perda estimada em estresse supera o limite indicado por Camila.","3. A plataforma oferece muitos produtos.","4. O retorno esperado é o mais alto entre as propostas.","5. O COE e o crédito de maior risco aumentam a complexidade da carteira.","6. O escritório conhece bem o setor de tecnologia."]},{"id":"risco","tipo":"opcao","rotulo":"Prumo Investimentos — maior risco para Camila (diferente do atrativo escolhido)","obrigatorio":true,"opcoes":["1. A taxa explícita é a menor entre as propostas.","2. A perda estimada em estresse supera o limite indicado por Camila.","3. A plataforma oferece muitos produtos.","4. O retorno esperado é o mais alto entre as propostas.","5. O COE e o crédito de maior risco aumentam a complexidade da carteira.","6. O escritório conhece bem o setor de tecnologia."]}]$$::jsonb, NULL, $${"referencias":{"atrativo":"1. A taxa explícita é a menor entre as propostas.","risco":"2. A perda estimada em estresse supera o limite indicado por Camila."},"outrasEscolhasDefensaveis":["Risco 5: a complexidade contraria o pedido de simplicidade de Camila."],"cuidado":"Retorno esperado alto (opção 4) não é automaticamente o maior atrativo: só ajuda se vier com um risco que ela aceite e produtos que ela entenda."}$$::jsonb),
('wm-task-negociacao', 'wm-simplificado', 'wm-cp-4', $$Transformar o risco em negociação$$, $$Pergunta aberta 2 — Transformar o risco em negociação. Escolha uma das propostas e pense no risco que você identificou nela.$$, $$[{"id":"proposta_escolhida","tipo":"opcao","rotulo":"Proposta escolhida","obrigatorio":true,"opcoes":["Banco Horizonte","Vértice Consultoria","Prumo Investimentos"]},{"id":"aberta_2","tipo":"texto","rotulo":"Que ajuste ou esclarecimento você pediria para reduzir o risco identificado? (até 80 palavras)","obrigatorio":true,"limiteCaracteres":560}]$$::jsonb, NULL, $${"avaliacao":{"aberta_2":"Um ajuste conectado ao risco escolhido, como diversificar o CDB do Horizonte entre emissores ou reduzir ações de tecnologia na Prumo."},"observacao":"Não exigir uma proposta específica."}$$::jsonb),
('wm-task-comparacao', 'wm-simplificado', 'wm-cp-5', $$Comparando as propostas$$, $$Compare as três propostas com quatro ideias: o retorno esperado (uma estimativa, não uma garantia), a perda estimada em estresse (quanto a carteira poderia cair em um ano muito ruim), o custo total (taxas e outras remunerações, aplicado sobre o patrimônio) e a liquidez (a facilidade de transformar o investimento em dinheiro sem perda relevante). A tabela de propostas está ao lado. Os números são fictícios; desconsidere impostos nesta etapa.
[[continuar]]
[[campos: pergunta_4]]
Pergunta 4 — Comparação.
[[continuar]]
[[campos: aberta_3]]
Pergunta aberta 3 — Recomendação inicial. Qual proposta você priorizaria agora?$$, $$[{"id":"pergunta_4","tipo":"opcao","rotulo":"Qual afirmação está correta?","obrigatorio":true,"opcoes":["A. A Prumo é a melhor opção porque tem o maior retorno esperado e o menor custo explícito.","B. O COE da Prumo garante que Camila terá os R$ 800 mil em qualquer situação.","C. O Horizonte tem a menor perda estimada e o maior custo, cerca de R$ 28,8 mil por ano; a Vértice fica dentro do limite de perda com custo de R$ 21,6 mil; a Prumo tem o menor custo explícito, mas supera o limite de perda.","D. As três carteiras de longo prazo têm o mesmo risco, pois todas incluem renda fixa."]},{"id":"aberta_3","tipo":"texto","rotulo":"Qual proposta você priorizaria agora? Apresente um motivo ligado ao que Camila pediu e a principal concessão que ela faria ao aceitar essa proposta. (até 100 palavras)","obrigatorio":true,"limiteCaracteres":700}]$$::jsonb, $${"titulo":"Comparação das propostas (valores fictícios). Retornos e perdas são estimativas, não garantias. Desconsidere impostos nesta etapa.","colunas":["Banco Horizonte","Vértice Consultoria","Prumo Investimentos"],"linhas":[{"rotulo":"Reserva do apartamento (R$ 800 mil)","celulas":[{"texto":"CDB do próprio banco com vencimento em dois anos.","valor":null},{"texto":"Títulos públicos e CDBs de três bancos diferentes, com vencimento em dois anos.","valor":null},{"texto":"COE com capital protegido no vencimento, atrelado a ações americanas, prazo de dois anos.","valor":null}]},{"rotulo":"Carteira de longo prazo (R$ 1,6 milhão)","celulas":[{"texto":"50% fundos multimercado da casa, 30% renda fixa e 20% ações.","valor":null},{"texto":"45% títulos atrelados à inflação, 35% ETFs de ações do Brasil e do exterior e 20% renda fixa pós-fixada.","valor":null},{"texto":"40% ações de tecnologia, 30% crédito privado de maior risco e 30% renda fixa pós-fixada.","valor":null}]},{"rotulo":"Retorno real esperado da carteira de longo prazo","celulas":[{"texto":"4,5% ao ano.","valor":4.5},{"texto":"5,0% ao ano.","valor":5},{"texto":"6,5% ao ano.","valor":6.5}]},{"rotulo":"Perda estimada em cenário de estresse (longo prazo)","celulas":[{"texto":"−11%.","valor":-11},{"texto":"−14%.","valor":-14},{"texto":"−24%.","valor":-24}]},{"rotulo":"Custo total anual sobre os R$ 2,4 milhões","celulas":[{"texto":"1,2% ao ano, embutido nos fundos.","valor":1.2},{"texto":"0,9% ao ano, taxa fixa da consultoria.","valor":0.9},{"texto":"0,8% ao ano explícito, além de receitas recebidas de alguns produtos.","valor":0.8}]},{"rotulo":"Atendimento","celulas":[{"texto":"Banker dedicada; reuniões trimestrais.","valor":null},{"texto":"Reuniões trimestrais; a cliente executa as ordens.","valor":null},{"texto":"Assessor dedicado; contato frequente.","valor":null}]}]}$$::jsonb, $${"referencias":{"pergunta_4":"C. O Horizonte tem a menor perda estimada e o maior custo, cerca de R$ 28,8 mil por ano; a Vértice fica dentro do limite de perda com custo de R$ 21,6 mil; a Prumo tem o menor custo explícito, mas supera o limite de perda."},"justificativas":{"pergunta_4":"Separa custo, risco e retorno: R$ 2,4 mi × 1,2% = R$ 28,8 mil; × 0,9% = R$ 21,6 mil; × 0,8% = R$ 19,2 mil. A ignora o limite de perda; B ignora que a proteção do COE vale no vencimento e depende do emissor, sem cobertura do FGC."},"custosAnuais":{"horizonte":28.8,"vertice":21.6,"prumo":19.2},"avaliacao":{"aberta_3":"Relação com o pedido de Camila e reconhecimento de uma concessão. Não exigir uma proposta específica: a participante pode manter ou mudar sua escolha, desde que explique sua decisão."}}$$::jsonb),
('wm-task-nova-informacao', 'wm-simplificado', 'wm-cp-6', $$Nova informação$$, $$Camila volta a conversar com você:
Camila: “Meu irmão e eu decidimos reformar a casa da minha mãe no ano que vem. Minha parte será de uns R$ 150 mil. E fiquei insegura com a Vértice: tenho medo de errar ao executar as ordens sozinha.”
A Vértice responde:
Vértice: “Podemos enviar um passo a passo de cada ordem e revisar a execução por videochamada. Não fazemos a custódia nem executamos ordens pela cliente, porque esse é o nosso modelo independente.”
[[continuar]]
[[campos: aberta_4]]
Pergunta aberta 4 — Reagir e ajustar.$$, $$[{"id":"aberta_4","tipo":"texto","rotulo":"Essas informações mudam sua recomendação? O que você ajustaria ou esclareceria antes de avançar? (até 100 palavras)","obrigatorio":true,"limiteCaracteres":700}]$$::jsonb, NULL, $${"avaliacao":{"aberta_4":"Separar os R$ 150 mil com liquidez no prazo da reforma e tratar a insegurança operacional com uma condição concreta."},"observacao":"Não exigir uma proposta específica: a participante pode manter ou mudar sua escolha, desde que explique sua decisão."}$$::jsonb),
('wm-task-pitch', 'wm-simplificado', 'wm-cp-7', $$Recomendação à cliente$$, $$Pergunta aberta 5 — Recomendação à cliente. Apresente sua recomendação a Camila. Formato: até um minuto de fala ou 150 palavras.$$, $$[{"id":"aberta_5","tipo":"texto","rotulo":"Explique o caminho escolhido, a principal concessão e as condições necessárias para avançar. (até 150 palavras)","obrigatorio":true,"limiteCaracteres":1050}]$$::jsonb, NULL, $${"avaliacao":{"aberta_5":"Recomendação coerente, reconhecimento de desvantagem e próximo passo claro."},"observacao":"Não exigir uma proposta específica: a participante pode manter ou mudar sua escolha, desde que explique sua decisão."}$$::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'wm-complexo',
  $$WM completo: o patrimônio de Helena Prado$$,
  'wealth-management',
  $$Projete o patrimônio de uma cliente que vendeu sua rede de clínicas, avalie seus objetivos, proponha uma alocação, estime custos sucessórios e pesquise cinco produtos reais.$$,
  $$Avaliar se o patrimônio sustenta os objetivos de Helena, propor uma alocação adequada, estimar custos sucessórios simplificados e identificar cinco produtos ou veículos reais para a estratégia.$$,
  $$Você trabalha como estagiária em uma equipe de Wealth Management que assessora Helena Prado, 58 anos. Helena vendeu sua rede de clínicas odontológicas e hoje tem R$ 14,4 milhões em patrimônio financeiro. Você vai projetar o fluxo patrimonial, avaliar a sustentabilidade dos objetivos, propor uma alocação de ativos, estimar o ITCMD e pesquisar cinco produtos ou veículos reais. Helena e as classes de ativos são fictícias. Os valores estão em R$ mil, em reais de 2025, salvo indicação contrária, e a data-base é 31/12/2025.$$,
  $${"resumo":"Em Wealth Management, a equipe avalia se o patrimônio de uma cliente sustenta seus objetivos, propõe uma alocação de ativos, considera a sucessão e pesquisa produtos para a estratégia. Neste case, você analisa o patrimônio de Helena Prado, uma cliente fictícia que vendeu sua rede de clínicas.","links":[],"cards":[{"titulo":"Projeção patrimonial","texto":"Estima a evolução do patrimônio ao longo dos anos, considerando retorno, entradas, retiradas e eventos previstos. É preciso informar quando cada fluxo começa e termina e a convenção de tempo, por exemplo retorno sobre o saldo inicial e fluxos ao fim do ano.","naPratica":"Se o patrimônio necessário para sustentar a aposentadoria é maior que o projetado, a cliente pode poupar mais, gastar menos, trabalhar por mais tempo ou aceitar mais risco."},{"titulo":"Retorno real e coerência","texto":"O retorno real desconta a inflação e mostra o ganho de poder de compra. Valores reais combinam com retornos reais; valores nominais, com retornos nominais. Misturar as duas bases aplica a inflação duas vezes.","naPratica":"Um investimento que rende 10% com inflação de 6% aumenta o poder de compra em cerca de 3,8%, não em 10%."},{"titulo":"Alocação de ativos e perda em estresse","texto":"A alocação de ativos é a divisão do patrimônio entre classes. O retorno esperado da carteira é a média dos retornos ponderada pelos pesos; a perda em estresse segue a mesma lógica com as perdas de cada classe. A alocação em geral explica mais do resultado de longo prazo do que a escolha de cada produto.","naPratica":"Uma carteira de 60% em renda fixa (5%) e 40% em ações (9%) tem retorno esperado de 0,6 × 5% + 0,4 × 9% = 6,6%."},{"titulo":"Concentração, liquidez e proteção","texto":"Concentrar o patrimônio em poucos ativos ou emissores aumenta o risco. O FGC cobre até R$ 250 mil por CPF por conglomerado financeiro, com teto global de R$ 1 milhão a cada quatro anos, em produtos como CDB, LCI, LCA e poupança. Títulos públicos, fundos, ações e COEs não têm essa cobertura. A reserva de liquidez deve cobrir as saídas dos próximos anos.","naPratica":"Com R$ 1 milhão em renda fixa bancária, dividir entre quatro conglomerados diferentes mantém tudo dentro da cobertura."},{"titulo":"Sucessão","texto":"Sem planejamento, os bens passam pelo inventário, com ITCMD e custos. Havendo herdeiros necessários, metade do patrimônio é a legítima. Testamento, doação em vida com usufruto, previdência e holding são ferramentas possíveis, cada uma com custos e limites.","naPratica":"Antes de discutir uma ferramenta, levante quem são os herdeiros, se há empresa ou imóveis, se a família conversa sobre o tema e quais são as regras do estado da cliente."},{"titulo":"Produtos reais e fontes","texto":"Pesquisar produtos significa descrever como funcionam, ligar argumentos à situação da cliente, apontar limitações e citar fontes. Fatos pesquisados e hipóteses devem ser separados.","naPratica":"Evite justificativas genéricas, como dizer apenas que o produto é seguro ou rentável."}],"comoSeEntra":{"ondeSeTrabalha":"Private banking de bancos, escritórios de assessoria de investimentos, consultorias de investimentos, gestoras de patrimônio e family offices, e planejamento financeiro.","formacoes":"Desde janeiro de 2026, as certificações de distribuição da ANBIMA são CPA, C-Pro R e C-Pro I. A CPA é a porta de entrada e pré-requisito para as demais; para planejamento financeiro, a certificação de referência é a CFP®.","vagas":"No estágio, o trabalho costuma ser apoiar relatórios, pesquisas de produtos, cadastro e preparação de reuniões. Depois vêm analista, assessora ou banker, banker sênior e head ou diretora. Os títulos e a divisão do trabalho variam entre instituições.","oQueAjuda":"Excel, comunicação (explicar conceitos técnicos de forma simples), conhecimento de produtos, ética e escuta: colocar o interesse da cliente em primeiro lugar e ser transparente sobre remuneração.","quandoRecrutam":"Os prazos variam entre as instituições. Acompanhe as páginas de carreira dos bancos, escritórios e consultorias."}}$$::jsonb,
  'publicado',
  8
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO checkpoints (id, case_id, "order", stage, title, description, points, task_ids) VALUES
('wm-cpc-1', 'wm-complexo', 1, 'entenda', $$Patrimônio, alocação e sucessão$$, $$Entenda como uma equipe de WM projeta o patrimônio, propõe uma alocação e considera a sucessão.$$, 15, $$[]$$::jsonb),
('wm-cpc-2', 'wm-complexo', 2, 'conteudos', $$Conteúdos do case$$, $$Leia todos os conteúdos do case antes de analisar o patrimônio de Helena.$$, 10, $$[]$$::jsonb),
('wm-cpc-3', 'wm-complexo', 3, 'situacao', $$Conheça Helena$$, $$Leia os fatos, calcule as concentrações e identifique os pontos de atenção e o que ainda é desconhecido.$$, 30, $$["wm-task-helena"]$$::jsonb),
('wm-cpc-4', 'wm-complexo', 4, 'situacao', $$Fluxo patrimonial$$, $$Projete o patrimônio de 2026 a 2035, estime o patrimônio necessário e faça a sensibilidade do retorno.$$, 40, $$["wm-task-fluxo"]$$::jsonb),
('wm-cpc-5', 'wm-complexo', 5, 'situacao', $$Alocação de ativos$$, $$Calcule a carteira atual, proponha uma carteira que respeite as restrições e explique a concessão.$$, 40, $$["wm-task-alocacao"]$$::jsonb),
('wm-cpc-6', 'wm-complexo', 6, 'situacao', $$Sucessão$$, $$Estime o ITCMD simplificado e liste o que levantar antes de discutir ferramentas sucessórias.$$, 30, $$["wm-task-sucessao"]$$::jsonb),
('wm-cpc-7', 'wm-complexo', 7, 'situacao', $$Produtos ou veículos reais$$, $$Pesquise cinco produtos ou veículos reais e explique por que poderiam fazer parte da estratégia de Helena.$$, 35, $$["wm-task-produtos"]$$::jsonb),
('wm-cpc-8', 'wm-complexo', 8, 'defesa', $$Conclusão e defesa$$, $$Apresente diagnóstico, recomendação, principal concessão, sensibilidade e três informações a confirmar.$$, 40, $$["wm-task-conclusao"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
('wm-task-helena', 'wm-complexo', 'wm-cpc-3', $$Conheça Helena$$, $$Você trabalha como estagiária em uma equipe de Wealth Management que assessora Helena Prado, 58 anos. Helena vendeu sua rede de clínicas odontológicas e hoje tem R$ 14,4 milhões em patrimônio financeiro. Sua missão é avaliar se o patrimônio sustenta os objetivos de Helena, propor uma alocação adequada, estimar custos sucessórios simplificados e identificar cinco produtos ou veículos reais que poderiam fazer parte da estratégia.
Helena e as classes de ativos são fictícias. Os valores estão em R$ mil, em reais de 2025 (já descontada a inflação), salvo indicação contrária. A data-base é 31/12/2025.
Helena é viúva e tem dois filhos adultos, Marcos e Júlia, e dois netos. Depois da venda da empresa, passou a integrar o conselho consultivo do comprador até 2032. Durante as reuniões iniciais, sua equipe reuniu as seguintes informações:
• Helena quer parar de trabalhar a partir de 2033 e manter o padrão de vida atual.
• Pretende comprar uma casa de praia em 2027 para reunir a família.
• Quer pagar os estudos dos netos: Pedro, de 2027 a 2031, e Lia, de 2030 a 2034.
• Possui um imóvel comercial alugado e o apartamento onde mora, sem dívidas.
• Cerca de R$ 12 milhões estão em uma aplicação de liquidez diária em um único banco desde a venda.
• Mantém R$ 1,8 milhão em ações de uma única empresa listada, onde trabalhou no início da carreira. Diz ter “carinho” por essa posição.
• Em 2020, resgatou investimentos em ações logo após uma queda forte e se arrependeu.
• Diz aceitar uma perda temporária de até R$ 1,8 milhão em um ano muito ruim, mas não mais do que isso.
• Quer deixar o patrimônio aos filhos em partes iguais e ouviu falar de holding e previdência para sucessão, mas não sabe se fazem sentido.
• Os filhos não sabem quanto Helena tem e não participam das decisões.
Bens não financeiros (não entram no patrimônio financeiro): apartamento de residência e imóvel comercial alugado.$$, $$[{"id":"pct_banco","tipo":"numerico","rotulo":"Que parcela do patrimônio financeiro está na aplicação do único banco?","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 12,4"},{"id":"pct_acao","tipo":"numerico","rotulo":"Que parcela do patrimônio financeiro está na ação de uma única empresa?","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 12,4"},{"id":"pontos_atencao","tipo":"texto","rotulo":"Cite dois ou três pontos de atenção que você identifica na situação de Helena, ligando cada um a um fato do enunciado.","obrigatorio":true,"limiteCaracteres":700},{"id":"o_que_falta","tipo":"texto","rotulo":"Que informações ainda são desconhecidas e fariam diferença na estratégia?","obrigatorio":true,"limiteCaracteres":450}]$$::jsonb, $${"titulo":"Patrimônio financeiro de Helena em 31/12/2025 (R$ mil, reais de 2025)","colunas":["Valor"],"linhas":[{"rotulo":"Aplicação de liquidez diária em um único banco","celulas":[{"texto":"12.000","valor":12000}]},{"rotulo":"Ações de uma única empresa listada","celulas":[{"texto":"1.800","valor":1800}]},{"rotulo":"Títulos públicos atrelados à inflação","celulas":[{"texto":"600","valor":600}]},{"rotulo":"Patrimônio financeiro total","celulas":[{"texto":"14.400","valor":14400}]}]}$$::jsonb, $${"referencias":{"pct_banco":83.3,"pct_acao":12.5,"tolerancia":0.1},"avaliacao":"Cálculo: 12.000 ÷ 14.400 = 83,3% e 1.800 ÷ 14.400 = 12,5%. Pontos de leitura do guia: o principal problema não é retorno, e sim a concentração em um único banco (muito acima do FGC), em uma única ação e a ausência de plano sucessório. Aceitar também o comportamento em 2020 (resgate após queda) como sinal sobre a tolerância real a risco, e o fato de os filhos não participarem. Exigir conexão com fatos do enunciado."}$$::jsonb),
('wm-task-fluxo', 'wm-complexo', 'wm-cpc-4', $$Fluxo patrimonial e sustentabilidade$$, $$Todos os valores são anuais, em R$ mil, em reais de 2025, já líquidos de impostos (tabela ao lado). Considere que o retorno de cada ano incide sobre o patrimônio financeiro do início do ano e que entradas e saídas ocorrem ao fim do ano. Os retornos são reais e líquidos de impostos e custos. O patrimônio financeiro inicial, em 31/12/2025, é de R$ 14.400 mil.
[[continuar]]
[[campos: retirada_liquida, saidas_2026_2027]]
Antes de projetar, identifique dois números. A partir de 2036, considere que Helena terá apenas o aluguel como entrada e manterá os gastos de vida e a manutenção da casa. Nos anos de 2026 e 2027, olhe apenas para as saídas líquidas, isto é, saídas menos entradas.
[[continuar]]
[[campos: pat_2035_35, nec_35, pat_2035_45, nec_45, pat_2035_55, nec_55]]
Projete o patrimônio financeiro de 2026 a 2035 e estime o patrimônio necessário em 31/12/2035 para sustentar indefinidamente, em termos reais, a retirada líquida a partir de 2036. Faça isso com retornos reais de 3,5%, 4,5% e 5,5% ao ano (sensibilidade).
[[continuar]]
[[campos: leitura, planilha_fluxo]]
Compare o patrimônio projetado com o necessário.$$, $$[{"id":"retirada_liquida","tipo":"numerico","rotulo":"Retirada líquida anual a partir de 2036","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal. Ex.: 485"},{"id":"saidas_2026_2027","tipo":"numerico","rotulo":"Saídas líquidas acumuladas de 2026 e 2027 (saídas menos entradas)","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"pat_2035_35","tipo":"numerico","rotulo":"Patrimônio financeiro em 31/12/2035 com retorno real de 3,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"nec_35","tipo":"numerico","rotulo":"Patrimônio necessário em 31/12/2035 com retorno real de 3,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"pat_2035_45","tipo":"numerico","rotulo":"Patrimônio financeiro em 31/12/2035 com retorno real de 4,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"nec_45","tipo":"numerico","rotulo":"Patrimônio necessário em 31/12/2035 com retorno real de 4,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"pat_2035_55","tipo":"numerico","rotulo":"Patrimônio financeiro em 31/12/2035 com retorno real de 5,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"nec_55","tipo":"numerico","rotulo":"Patrimônio necessário em 31/12/2035 com retorno real de 5,5%","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"leitura","tipo":"texto","rotulo":"O plano é sustentável em cada cenário? Como a folga muda com o retorno e o que isso diz sobre o risco do plano?","obrigatorio":true,"limiteCaracteres":700},{"id":"planilha_fluxo","tipo":"arquivo","rotulo":"Anexar a Aba 1 — Fluxo patrimonial (planilha)","obrigatorio":false,"dica":"PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, $${"titulo":"Fluxos anuais (R$ mil, reais de 2025, líquidos de impostos)","colunas":["Valor anual","Período"],"linhas":[{"rotulo":"Aluguel do imóvel comercial (entrada)","celulas":[{"texto":"100","valor":100},{"texto":"2026 em diante","valor":null}]},{"rotulo":"Remuneração do conselho (entrada)","celulas":[{"texto":"300","valor":300},{"texto":"2026 a 2032","valor":null}]},{"rotulo":"Gastos de vida (saída)","celulas":[{"texto":"540","valor":540},{"texto":"2026 em diante","valor":null}]},{"rotulo":"Estudos de Pedro (saída)","celulas":[{"texto":"120","valor":120},{"texto":"2027 a 2031","valor":null}]},{"rotulo":"Estudos de Lia (saída)","celulas":[{"texto":"120","valor":120},{"texto":"2030 a 2034","valor":null}]},{"rotulo":"Compra da casa de praia (saída única)","celulas":[{"texto":"1.500","valor":1500},{"texto":"2027","valor":null}]},{"rotulo":"Manutenção da casa de praia (saída)","celulas":[{"texto":"45","valor":45},{"texto":"2028 em diante","valor":null}]}]}$$::jsonb, $${"referencias":{"retirada_liquida":485,"saidas_2026_2027":1900,"pat_2035_35":13951,"nec_35":13857,"folga_35":94,"pat_2035_45":15677,"nec_45":10778,"folga_45":4899,"pat_2035_55":17569,"nec_55":8818,"folga_55":8750,"tolerancia_relativa":0.01},"passoAPasso":"Retirada líquida a partir de 2036: 540 + 45 − 100 = 485 por ano. Saídas líquidas: 2026 = 540 − 400 = 140; 2027 = 540 + 120 + 1.500 − 400 = 1.760; total 1.900 (mínimo a manter em C1). Patrimônio necessário = 485 ÷ retorno real. Patrimônio ao fim de cada ano = saldo inicial × (1 + retorno) + entradas − saídas.","tabelaDeReferencia":{"3,5%":{"patrimonio2035":13951,"necessario":13857,"folga":94},"4,0%":{"patrimonio2035":14794,"necessario":12125,"folga":2669},"4,5%":{"patrimonio2035":15677,"necessario":10778,"folga":4899},"5,0%":{"patrimonio2035":16601,"necessario":9700,"folga":6901},"5,5%":{"patrimonio2035":17569,"necessario":8818,"folga":8751}},"saldoAnualDeReferencia4_5":{"2026":14908,"2027":13819,"2028":14136,"2029":14467,"2030":14693,"2031":14929,"2032":15296,"2033":15379,"2034":15466,"2035":15677},"avaliacao":{"leitura":"O plano é viável mesmo com a carteira atual, mas com folga pequena em 3,5% (94 mil). O principal problema não é retorno, e sim concentração e ausência de plano sucessório. Valores de folga recalculados a partir dos números exatos podem diferir em 1 mil dos do guia por arredondamento (8.750 x 8.751 em 5,5%)."}}$$::jsonb),
('wm-task-alocacao', 'wm-complexo', 'wm-cpc-5', $$Alocação: carteira atual e proposta$$, $$A tabela ao lado reúne classes de ativos fictícias. Retornos são reais e anuais; perdas consideram um ano de estresse severo. Para a posição atual em ações de uma única empresa, considere retorno real esperado de 7,0% e perda em estresse de −45%.
[[continuar]]
[[campos: retorno_atual, perda_atual_valor, perda_atual_pct]]
Calcule o retorno real esperado e a perda em estresse da carteira atual: R$ 12.000 mil em C1, R$ 1.800 mil na ação de uma única empresa e R$ 600 mil em C2.
[[continuar]]
[[campos: peso_c1, peso_c2, peso_c3, peso_c4, peso_c5, peso_c6, peso_c7, peso_acao_unica]]
Proponha uma carteira com pesos por classe (os pesos devem somar 100%) que respeite três restrições: perda em estresse de no máximo R$ 1,8 milhão; recursos em C1 suficientes para as saídas líquidas de 2026 e 2027; e no máximo 5% do patrimônio em uma única empresa. Mais de uma carteira é defensável.
[[continuar]]
[[campos: retorno_proposta, perda_proposta_valor, perda_proposta_pct, restr_perda, restr_caixa, restr_concentracao, pat_2035_proposta, nec_proposta]]
Calcule o retorno esperado e a perda em estresse da sua carteira, verifique as três restrições e projete o patrimônio de 2035 e o patrimônio necessário com o retorno da sua carteira.
[[continuar]]
[[campos: concessao, acao_unica]]
Compare as duas carteiras e explique a principal concessão da proposta.$$, $$[{"id":"retorno_atual","tipo":"numerico","rotulo":"Retorno real esperado da carteira atual","obrigatorio":true,"unidade":"% ao ano","dica":"Use vírgula como separador decimal. Ex.: 4,0"},{"id":"perda_atual_valor","tipo":"numerico","rotulo":"Perda em estresse da carteira atual","obrigatorio":true,"unidade":"R$ mil","dica":"Informe o valor da perda como número positivo."},{"id":"perda_atual_pct","tipo":"numerico","rotulo":"Perda em estresse da carteira atual","obrigatorio":true,"unidade":"% do patrimônio","dica":"Informe como número positivo. Ex.: 6,0"},{"id":"peso_c1","tipo":"numerico","rotulo":"Peso em C1 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c2","tipo":"numerico","rotulo":"Peso em C2 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c3","tipo":"numerico","rotulo":"Peso em C3 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c4","tipo":"numerico","rotulo":"Peso em C4 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c5","tipo":"numerico","rotulo":"Peso em C5 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c6","tipo":"numerico","rotulo":"Peso em C6 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_c7","tipo":"numerico","rotulo":"Peso em C7 na carteira proposta","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 20"},{"id":"peso_acao_unica","tipo":"numerico","rotulo":"Peso das ações da empresa única na carteira proposta (0 se zeradas)","obrigatorio":true,"unidade":"%","dica":"Use vírgula como separador decimal. Ex.: 0"},{"id":"retorno_proposta","tipo":"numerico","rotulo":"Retorno real esperado da carteira proposta","obrigatorio":true,"unidade":"% ao ano","dica":"Use vírgula como separador decimal. Ex.: 5,1"},{"id":"perda_proposta_valor","tipo":"numerico","rotulo":"Perda em estresse da carteira proposta","obrigatorio":true,"unidade":"R$ mil","dica":"Informe o valor da perda como número positivo."},{"id":"perda_proposta_pct","tipo":"numerico","rotulo":"Perda em estresse da carteira proposta","obrigatorio":true,"unidade":"% do patrimônio","dica":"Informe como número positivo. Ex.: 9,8"},{"id":"restr_perda","tipo":"opcao","rotulo":"Sua carteira respeita a perda máxima de R$ 1,8 milhão em estresse?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"restr_caixa","tipo":"opcao","rotulo":"Sua carteira mantém em C1 recursos suficientes para as saídas líquidas de 2026 e 2027?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"restr_concentracao","tipo":"opcao","rotulo":"Sua carteira mantém no máximo 5% do patrimônio em uma única empresa?","obrigatorio":true,"opcoes":["Sim","Não"]},{"id":"pat_2035_proposta","tipo":"numerico","rotulo":"Patrimônio financeiro em 31/12/2035 com o retorno da sua carteira","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"nec_proposta","tipo":"numerico","rotulo":"Patrimônio necessário em 31/12/2035 com o retorno da sua carteira","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"concessao","tipo":"texto","rotulo":"Compare as duas carteiras e explique a principal concessão da proposta.","obrigatorio":true,"limiteCaracteres":700},{"id":"acao_unica","tipo":"texto","rotulo":"Se decidiu manter parte das ações da empresa por preferência de Helena, explique como e por quanto tempo. Se zerou, explique como trataria o “carinho” de Helena.","obrigatorio":true,"limiteCaracteres":500},{"id":"planilha_alocacao","tipo":"arquivo","rotulo":"Anexar a Aba 2 — Alocação (planilha)","obrigatorio":false,"dica":"PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, $${"titulo":"Classes de ativos fictícias. Retornos são reais e anuais; perdas consideram um ano de estresse severo.","colunas":["Retorno real esperado","Perda em estresse","Liquidez","Observações"],"linhas":[{"rotulo":"C1 — Caixa e renda fixa pós-fixada de liquidez diária","celulas":[{"texto":"3,5%","valor":3.5},{"texto":"0%","valor":0},{"texto":"Imediata","valor":null},{"texto":"Baixa oscilação; risco de emissor.","valor":null}]},{"rotulo":"C2 — Títulos públicos atrelados à inflação","celulas":[{"texto":"5,0%","valor":5},{"texto":"−8%","valor":-8},{"texto":"1 dia útil","valor":null},{"texto":"Oscila antes do vencimento.","valor":null}]},{"rotulo":"C3 — Crédito privado de alta qualidade","celulas":[{"texto":"5,5%","valor":5.5},{"texto":"−6%","valor":-6},{"texto":"30 dias","valor":null},{"texto":"Risco de crédito; diversificação necessária.","valor":null}]},{"rotulo":"C4 — Fundos multimercado","celulas":[{"texto":"5,5%","valor":5.5},{"texto":"−8%","valor":-8},{"texto":"30 dias","valor":null},{"texto":"Resultado depende da gestora.","valor":null}]},{"rotulo":"C5 — Ações brasileiras diversificadas","celulas":[{"texto":"7,0%","valor":7},{"texto":"−30%","valor":-30},{"texto":"2 dias úteis","valor":null},{"texto":"Alta oscilação.","valor":null}]},{"rotulo":"C6 — Ações globais diversificadas","celulas":[{"texto":"6,0%","valor":6},{"texto":"−22%","valor":-22},{"texto":"2 dias úteis","valor":null},{"texto":"Exposição cambial.","valor":null}]},{"rotulo":"C7 — Fundos imobiliários","celulas":[{"texto":"5,5%","valor":5.5},{"texto":"−18%","valor":-18},{"texto":"2 dias úteis","valor":null},{"texto":"Renda mensal; oscilação de cotas.","valor":null}]},{"rotulo":"Ação de uma única empresa (posição atual de Helena)","celulas":[{"texto":"7,0%","valor":7},{"texto":"−45%","valor":-45},{"texto":"—","valor":null},{"texto":"Dado da posição atual; não é uma das sete classes.","valor":null}]}]}$$::jsonb, $${"referencias":{"retorno_atual":4,"perda_atual_valor":858,"perda_atual_pct":6,"tolerancia_relativa":0.02},"carteiraAtual":"Retorno: (12.000 × 3,5% + 1.800 × 7,0% + 600 × 5,0%) ÷ 14.400 = 4,0% ao ano. Perda em estresse: 1.800 × 45% + 600 × 8% = 810 + 48 = R$ 858 mil (6,0%), concentrada na ação única.","restricoes":{"perdaMaximaRsMil":1800,"perdaMaximaPctPatrimonio":12.5,"caixaMinimoC1RsMil":1900,"caixaMinimoC1Pct":13.2,"acaoUnicaMaximaPct":5,"acaoUnicaMaximaRsMil":720},"carteiraDeReferencia":{"pesos":{"peso_c1":20,"peso_c2":35,"peso_c3":12,"peso_c4":10,"peso_c5":8,"peso_c6":10,"peso_c7":5,"peso_acao_unica":0},"retornoRealEsperado":5.1,"perdaEstresse":{"pct":9.82,"rsMil":1414},"patrimonio2035":16782,"patrimonioNecessario2035":9519,"folga":7263,"observacao":"Sem a ação única, retorno real de cerca de 5,1% e perda em estresse de −9,8% (cerca de R$ 1,41 milhão). Os pesos somam 100%."},"avaliacao":"Verificar: pesos somam 100%; retorno = soma de peso × retorno de cada classe; perda = soma de peso × perda de cada classe, vezes R$ 14.400 mil; as três restrições; patrimônio de 2035 recalculado com o retorno informado (mesma convenção: retorno sobre o saldo inicial, fluxos ao fim do ano). Mais de uma carteira é defensável. Uma carteira mais conservadora que a de referência também pode ser defensável, desde que a participante mostre a folga. Se mantiver parte da ação por preferência de Helena, aceitar com limite de 5% e prazo explicados. A restrição de 5% por empresa e a perda de R$ 1,8 mi devem ser respeitadas pela carteira proposta; o respectivo campo Sim/Não deve ser coerente com os pesos informados."}$$::jsonb),
('wm-task-sucessao', 'wm-complexo', 'wm-cpc-6', $$Sucessão: ITCMD e informações a levantar$$, $$Para fins do case, considere uma alíquota de ITCMD de 8% sobre o patrimônio financeiro transmitido, sem outras despesas. Estime o imposto se o patrimônio projetado em 2035 fosse transmitido pelo inventário.
[[continuar]]
[[campos: itcmd_base, itcmd, informacoes]]
As regras de ITCMD e da previdência mudaram recentemente em vários estados; trate-as como pontos a pesquisar e confirmar. Explique que informações você precisaria levantar antes de discutir holding, previdência ou doação em vida com Helena.$$, $$[{"id":"itcmd_base","tipo":"numerico","rotulo":"Patrimônio projetado em 2035 que você usou (indique o retorno real adotado na Aba 3)","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"itcmd","tipo":"numerico","rotulo":"ITCMD estimado a 8% sobre esse patrimônio","obrigatorio":true,"unidade":"R$ mil","dica":"Use vírgula como separador decimal."},{"id":"informacoes","tipo":"texto","rotulo":"Que informações você precisaria levantar antes de discutir holding, previdência ou doação em vida com Helena? (até 150 palavras)","obrigatorio":true,"limiteCaracteres":1050},{"id":"planilha_sucessao","tipo":"arquivo","rotulo":"Anexar a Aba 3 — Sucessão e produtos (planilha)","obrigatorio":false,"dica":"PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, NULL, $${"referencias":{"itcmd_ref":1254,"base_ref":15677,"tolerancia_relativa":0.01},"avaliacao":{"itcmd":"O ITCMD deve ser 8% do patrimônio informado. Referência: 8% sobre R$ 15,7 milhões (cenário de 4,5%) = cerca de R$ 1,25 milhão. Verificar a coerência entre a base informada e o retorno adotado.","informacoes":"Procurar: quem são os herdeiros, se há empresa ou imóveis, se a família conversa sobre o tema, regras do estado da cliente (ITCMD e previdência), custos de cada ferramenta (testamento, doação em vida com usufruto, previdência, holding). Tratar regras como pontos a pesquisar e confirmar. Não ensinar fórmulas nem exigir ferramenta específica."}}$$::jsonb),
('wm-task-produtos', 'wm-complexo', 'wm-cpc-7', $$Cinco produtos ou veículos reais$$, $$Pesquise e selecione cinco produtos ou veículos reais que poderiam fazer parte da estratégia de Helena. Podem ser títulos públicos, ETFs, fundos, planos de previdência, estruturas sucessórias ou outros instrumentos.
Para cada um: apresente brevemente como funciona; desenvolva dois argumentos distintos ligados à situação de Helena; aponte uma limitação ou questão a investigar; inclua as fontes utilizadas.
Evite justificativas genéricas, como dizer apenas que o produto é seguro ou rentável. Diferencie fatos pesquisados de hipóteses. Não há uma lista fechada de produtos.$$, $$[{"id":"p1_nome","tipo":"texto","rotulo":"Produto ou veículo 1: nome","obrigatorio":true,"limiteCaracteres":150},{"id":"p1_descricao_argumentos","tipo":"texto","rotulo":"Produto ou veículo 1: como funciona (breve) e dois argumentos distintos ligados à situação de Helena","obrigatorio":true,"limiteCaracteres":900},{"id":"p1_limitacao","tipo":"texto","rotulo":"Produto ou veículo 1: uma limitação ou questão a investigar","obrigatorio":true,"limiteCaracteres":400},{"id":"p1_fontes","tipo":"texto","rotulo":"Produto ou veículo 1: fontes consultadas","obrigatorio":true,"limiteCaracteres":300},{"id":"p2_nome","tipo":"texto","rotulo":"Produto ou veículo 2: nome","obrigatorio":true,"limiteCaracteres":150},{"id":"p2_descricao_argumentos","tipo":"texto","rotulo":"Produto ou veículo 2: como funciona (breve) e dois argumentos distintos ligados à situação de Helena","obrigatorio":true,"limiteCaracteres":900},{"id":"p2_limitacao","tipo":"texto","rotulo":"Produto ou veículo 2: uma limitação ou questão a investigar","obrigatorio":true,"limiteCaracteres":400},{"id":"p2_fontes","tipo":"texto","rotulo":"Produto ou veículo 2: fontes consultadas","obrigatorio":true,"limiteCaracteres":300},{"id":"p3_nome","tipo":"texto","rotulo":"Produto ou veículo 3: nome","obrigatorio":true,"limiteCaracteres":150},{"id":"p3_descricao_argumentos","tipo":"texto","rotulo":"Produto ou veículo 3: como funciona (breve) e dois argumentos distintos ligados à situação de Helena","obrigatorio":true,"limiteCaracteres":900},{"id":"p3_limitacao","tipo":"texto","rotulo":"Produto ou veículo 3: uma limitação ou questão a investigar","obrigatorio":true,"limiteCaracteres":400},{"id":"p3_fontes","tipo":"texto","rotulo":"Produto ou veículo 3: fontes consultadas","obrigatorio":true,"limiteCaracteres":300},{"id":"p4_nome","tipo":"texto","rotulo":"Produto ou veículo 4: nome","obrigatorio":true,"limiteCaracteres":150},{"id":"p4_descricao_argumentos","tipo":"texto","rotulo":"Produto ou veículo 4: como funciona (breve) e dois argumentos distintos ligados à situação de Helena","obrigatorio":true,"limiteCaracteres":900},{"id":"p4_limitacao","tipo":"texto","rotulo":"Produto ou veículo 4: uma limitação ou questão a investigar","obrigatorio":true,"limiteCaracteres":400},{"id":"p4_fontes","tipo":"texto","rotulo":"Produto ou veículo 4: fontes consultadas","obrigatorio":true,"limiteCaracteres":300},{"id":"p5_nome","tipo":"texto","rotulo":"Produto ou veículo 5: nome","obrigatorio":true,"limiteCaracteres":150},{"id":"p5_descricao_argumentos","tipo":"texto","rotulo":"Produto ou veículo 5: como funciona (breve) e dois argumentos distintos ligados à situação de Helena","obrigatorio":true,"limiteCaracteres":900},{"id":"p5_limitacao","tipo":"texto","rotulo":"Produto ou veículo 5: uma limitação ou questão a investigar","obrigatorio":true,"limiteCaracteres":400},{"id":"p5_fontes","tipo":"texto","rotulo":"Produto ou veículo 5: fontes consultadas","obrigatorio":true,"limiteCaracteres":300},{"id":"planilha_produtos","tipo":"arquivo","rotulo":"Anexar a Aba 3 — Sucessão e produtos (opcional, se for a mesma planilha)","obrigatorio":false,"dica":"PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, NULL, $${"avaliacao":"Não há lista fechada de produtos nem recomendação de produto específico de uma instituição. Avaliar: (1) o produto ou veículo é real e a descrição é compatível com fontes públicas; (2) dois argumentos distintos, cada um ligado a um fato da situação de Helena (por exemplo, a reserva de liquidez, a concentração em um único banco acima do FGC, a sucessão em partes iguais); (3) limitação ou questão a investigar relevante; (4) fontes citadas e distinção entre fato pesquisado e hipótese. Penalizar justificativas genéricas, fatos inventados e fontes ausentes."}$$::jsonb),
('wm-task-conclusao', 'wm-complexo', 'wm-cpc-8', $$Conclusão e defesa$$, $$Escreva uma conclusão de até uma página, em linguagem objetiva, usando os resultados das tarefas anteriores. Ela deve trazer o diagnóstico, a recomendação, a principal concessão, uma sensibilidade simples do retorno e três informações a confirmar com Helena. Na defesa de cerca de 15 minutos, explique suas escolhas.$$, $$[{"id":"diagnostico","tipo":"texto","rotulo":"Diagnóstico da situação de Helena","obrigatorio":true,"limiteCaracteres":700},{"id":"recomendacao","tipo":"texto","rotulo":"Recomendação (alocação, liquidez e próximos passos)","obrigatorio":true,"limiteCaracteres":900},{"id":"concessao","tipo":"texto","rotulo":"Principal concessão da sua recomendação","obrigatorio":true,"limiteCaracteres":500},{"id":"sensibilidade","tipo":"texto","rotulo":"Sensibilidade simples do retorno: o que muda no plano se o retorno real for menor ou maior?","obrigatorio":true,"limiteCaracteres":600},{"id":"confirmar_1","tipo":"texto","rotulo":"Informação a confirmar com Helena (1)","obrigatorio":true,"limiteCaracteres":300},{"id":"confirmar_2","tipo":"texto","rotulo":"Informação a confirmar com Helena (2)","obrigatorio":true,"limiteCaracteres":300},{"id":"confirmar_3","tipo":"texto","rotulo":"Informação a confirmar com Helena (3)","obrigatorio":true,"limiteCaracteres":300},{"id":"planilha_final","tipo":"arquivo","rotulo":"Anexar a planilha completa (opcional)","obrigatorio":false,"dica":"PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, NULL, $${"avaliacao":"Não impor uma conclusão única. Pontos de leitura: o plano é viável mesmo com a carteira atual, mas com folga pequena em 3,5%; o principal problema não é retorno, e sim concentração em um único banco (muito acima do FGC), em uma única ação e ausência de plano sucessório. Uma carteira mais conservadora que a de referência também pode ser defensável, desde que a participante mostre a folga. Verificar sensibilidade coerente com a tabela de referência, principal concessão explícita e três informações a confirmar relevantes.","perguntasDeDefesa":["O plano de Helena é viável com a carteira atual? Qual é o problema principal dela, se não for o retorno?","Qual é a folga do seu plano com retorno de 3,5% e o que ela diz sobre o risco?","Qual foi a principal concessão da sua carteira e como você explicaria isso a Helena?","O que você precisaria confirmar antes de discutir holding, previdência ou doação em vida?"],"regraIA":"Se houver IA representando Helena, ela deve responder apenas com fatos definidos no case."}$$::jsonb)
